        "版本" to "Version",
        "版本号" to "Version code",
        "变体" to "Variant",
        "lite 版给低配机器用的：只留两种纯色界面，没有壁纸和模糊，图片淡入和条目动画也关了，阅读器预取更保守" to "The lite build is for low-end devices: only two solid-color themes, no wallpaper or blur, image fades and list animations are off, and the reader prefetches less",
        "检查更新" to "Check for updates",
        "检查中…" to "Checking…",
