        "已是最新版本（远端 %1\$s）" to "Already up to date (remote %1\$s)",
        "下载更新包（%1\$s）" to "Download update (%1\$s)",
        "一个安装包同时支持 arm64 与 x86_64，无需区分架构。若直链打不开，可改用下面的发布页自行挑选。" to "One APK supports both arm64 and x86_64, no need to pick an architecture. If the direct link doesn't open, use the releases page below.",
        "更新内容：%1\$s" to "What's new: %1\$s",
        "说明" to "Notes",
        "禁漫（JMComic）的第三方客户端，Kotlin 与 Compose 写的。没有插槽广告，也不记录你在看什么；登录凭证加密之后才写到本地\\n\\n阅读器有纵向滚动和双页两种，长图拼接不留接缝。收藏、进度、屏蔽名单都在本地，也能通过 WebDAV 同步到你自己的网盘。屏蔽按关键词、分类、标签走，命中就从列表里消失" to "A third-party client for JMComic, written in Kotlin and Compose. No interstitial ads, and it doesn't record what you read; login credentials are encrypted before being written to disk\\n\\nThere are two reader layouts, vertical scrolling and page flipping, with seamless stitching for long images. Favorites, progress and block lists live on your device, and can sync to your own cloud drive via WebDAV. Blocking works by keyword, category or tag, and matching works disappear from lists",
