        "底栏变成浮在内容之上的胶囊，选中项带一块会滑过去的底。" to "The tab bar becomes a pill floating above the content, with a sliding indicator behind the selected item.",
        "玻璃不再覆盖底色，只留模糊与描边；文字自动加一圈反色柔光保证可读。" to "The glass no longer covers the base color, keeping only blur and outline; text gets a halo in the opposite color so it stays legible.",
        "用系统动态取色的主色 / 次色 / 第三色给背景与模糊层上色。需要开动态取色且系统为 Android 12+，否则这个开关不生效。" to "Tints the background and blur layer with the system's dynamic primary / secondary / tertiary colors. Requires dynamic color and Android 12+; otherwise this switch has no effect.",
        "Android 15 起由系统提供（返回手势中系统会推动整个窗口），本项不再生效，已停用。" to "Provided by the system since Android 15 (the system pushes the whole window during a back gesture), so this option no longer applies and is disabled.",
        "返回手势进行中，当前页跟手淡出，松手前就能看出要退出。" to "During a back gesture the current page fades with your finger, so you can tell it will exit before releasing.",
        "需要 Android 13 / 14；本机系统没有预测性返回手势，本项不生效。" to "Requires Android 13 / 14; this device has no predictive back gesture, so this option has no effect.",
        "每半天左右让系统挑个合适时机检查一次，有变化才提醒；同一批更新只提醒一次。只用连载列表和你本地的阅读时间，不上传你在看什么。默认关闭。" to "About twice a day the system picks a suitable moment to check, and only notifies when something changed; the same batch is reported once. It only uses the subscription list and your local reading times, and never uploads what you read. Off by default.",
        "取系统壁纸的配色（Android 12+）。Material 风格会整份跟随系统；另外几套玻璃只取强调色，层次仍按本站配色。" to "Take colors from the system wallpaper (Android 12+). The Material style follows the system entirely; the other glass styles only take the accent, keeping their own layered colors.",
        "自动更换：关闭" to "Auto change: off",
        "自动更换：每 %1\$s" to "Auto change: every %1\$s",
        "清除壁纸缓存" to "Clear wallpaper cache",
