        "说明" to "説明",
        "禁漫（JMComic）的第三方客户端，Kotlin 与 Compose 写的。没有插槽广告，也不记录你在看什么；登录凭证加密之后才写到本地\\n\\n阅读器有纵向滚动和双页两种，长图拼接不留接缝。收藏、进度、屏蔽名单都在本地，也能通过 WebDAV 同步到你自己的网盘。屏蔽按关键词、分类、标签走，命中就从列表里消失" to "Kotlin と Compose で書かれた JMComic のサードパーティクライアントです。インタースティシャル広告はなく、閲覧内容も記録しません。ログイン情報は暗号化してから端末に保存します\\n\\nリーダーは縦スクロールと見開きの2種類で、長い画像も継ぎ目なく連結します。お気に入り、進捗、ブロックリストは端末内に保存され、WebDAV で自分のクラウドに同期できます。ブロックはキーワード・カテゴリ・タグで指定でき、一致した作品は一覧から消えます",
