        "玻璃不再覆盖底色，只留模糊与描边；文字自动加一圈反色柔光保证可读。" to "ガラスが下地を覆わなくなり、ぼかしと縁取りだけが残ります。文字には反対色の柔らかい縁取りを付けて読みやすくします。",
        "用系统动态取色的主色 / 次色 / 第三色给背景与模糊层上色。需要开动态取色且系统为 Android 12+，否则这个开关不生效。" to "システムのダイナミックカラーの主色 / 副色 / 第三色で背景とぼかし層を着色します。ダイナミックカラーを有効にし、Android 12 以上が必要です。それ以外ではこのスイッチは効きません。",
        "Android 15 起由系统提供（返回手势中系统会推动整个窗口），本项不再生效，已停用。" to "Android 15 以降はシステムが提供するため（戻るジェスチャーでウィンドウ全体が動く）、この項目は無効になりました。",
        "返回手势进行中，当前页跟手淡出，松手前就能看出要退出。" to "戻るジェスチャー中は現在のページが指に追従してフェードし、離す前に終了すると分かります。",
        "需要 Android 13 / 14；本机系统没有预测性返回手势，本项不生效。" to "Android 13 / 14 が必要です。この端末には予測型戻るジェスチャーがないため、この項目は効きません。",
        "每半天左右让系统挑个合适时机检查一次，有变化才提醒；同一批更新只提醒一次。只用连载列表和你本地的阅读时间，不上传你在看什么。默认关闭。" to "半日ほどごとにシステムが適切なタイミングで確認し、変化があったときだけ通知します。同じ更新のまとまりは一度だけ通知します。フォロー中の作品と端末内の閲覧時刻だけを使い、何を読んだかは送信しません。既定はオフです。",
        "取系统壁纸的配色（Android 12+）。Material 风格会整份跟随系统；另外几套玻璃只取强调色，层次仍按本站配色。" to "システムの壁紙から配色を取得します（Android 12 以上）。Material スタイルは全体がシステムに従い、他のガラスはアクセント色だけを取り込み、階層は独自配色のままです。",
