        "玻璃不再覆盖底色，只留模糊与描边；文字自动加一圈反色柔光保证可读。" to "Стекло больше не закрывает фон: остаются только размытие и обводка, а текст получает ореол противоположного цвета для читаемости.",
        "用系统动态取色的主色 / 次色 / 第三色给背景与模糊层上色。需要开动态取色且系统为 Android 12+，否则这个开关不生效。" to "Окрашивает фон и слой размытия в основной / вторичный / третичный цвета динамической палитры. Нужны динамический цвет и Android 12+, иначе переключатель не действует.",
        "Android 15 起由系统提供（返回手势中系统会推动整个窗口），本项不再生效，已停用。" to "Начиная с Android 15 это обеспечивает система (при жесте «назад» сдвигается всё окно), поэтому пункт больше не действует и отключён.",
        "返回手势进行中，当前页跟手淡出，松手前就能看出要退出。" to "Во время жеста «назад» текущая страница затухает вслед за пальцем, так что до отпускания видно, что произойдёт выход.",
        "需要 Android 13 / 14；本机系统没有预测性返回手势，本项不生效。" to "Требуется Android 13 / 14; на этом устройстве нет жеста предсказуемого возврата, поэтому пункт не действует.",
        "每半天左右让系统挑个合适时机检查一次，有变化才提醒；同一批更新只提醒一次。只用连载列表和你本地的阅读时间，不上传你在看什么。默认关闭。" to "Примерно дважды в день система выбирает подходящий момент для проверки и сообщает только при изменениях; одна и та же пачка обновлений сообщается один раз. Используются только список подписок и локальное время чтения, что вы читаете — не отправляется. По умолчанию выключено.",
        "取系统壁纸的配色（Android 12+）。Material 风格会整份跟随系统；另外几套玻璃只取强调色，层次仍按本站配色。" to "Брать цвета системных обоев (Android 12+). Стиль Material следует за системой полностью; остальные стёкла берут только акцент, сохраняя свои слои.",
