        "禁漫（JMComic）的第三方客户端，Kotlin 与 Compose 写的。没有插槽广告，也不记录你在看什么；登录凭证加密之后才写到本地\\n\\n阅读器有纵向滚动和双页两种，长图拼接不留接缝。收藏、进度、屏蔽名单都在本地，也能通过 WebDAV 同步到你自己的网盘。屏蔽按关键词、分类、标签走，命中就从列表里消失" to "Kotlin과 Compose로 만든 JMComic 서드파티 클라이언트입니다. 전면 광고가 없고 무엇을 보는지 기록하지 않으며, 로그인 정보는 암호화한 뒤에만 기기에 저장합니다\\n\\n리더는 세로 스크롤과 페이지 넘김 두 가지이며, 긴 이미지도 이음매 없이 연결합니다. 즐겨찾기, 진행률, 차단 목록은 기기에 저장되고 WebDAV로 자신의 클라우드에 동기화할 수 있습니다. 차단은 키워드·카테고리·태그로 지정하며 일치하는 작품은 목록에서 사라집니다",
