        "自动更换" to "자동 변경",
        "关闭" to "끔",
        "底栏变成浮在内容之上的胶囊，选中项带一块会滑过去的底。" to "하단 바가 콘텐츠 위에 떠 있는 알약 모양이 되고, 선택한 항목 뒤에서 밑판이 미끄러집니다.",
        "玻璃不再覆盖底色，只留模糊与描边；文字自动加一圈反色柔光保证可读。" to "유리가 바탕색을 덮지 않고 블러와 테두리만 남습니다. 글자에는 반대색 번짐을 둘러 읽기 쉽게 합니다.",
        "用系统动态取色的主色 / 次色 / 第三色给背景与模糊层上色。需要开动态取色且系统为 Android 12+，否则这个开关不生效。" to "시스템 동적 색상의 주색 / 보조색 / 제3색으로 배경과 블러 층을 물들입니다. 동적 색상을 켜고 Android 12 이상이어야 하며, 아니면 이 스위치는 효과가 없습니다.",
        "Android 15 起由系统提供（返回手势中系统会推动整个窗口），本项不再生效，已停用。" to "Android 15부터는 시스템이 제공하므로(뒤로 가기 동작에서 시스템이 창 전체를 밀어냄) 이 항목은 더 이상 적용되지 않아 비활성화됩니다.",
        "返回手势进行中，当前页跟手淡出，松手前就能看出要退出。" to "뒤로 가기 동작 중에는 현재 페이지가 손가락을 따라 흐려져, 놓기 전에 종료될 것임을 알 수 있습니다.",
        "需要 Android 13 / 14；本机系统没有预测性返回手势，本项不生效。" to "Android 13 / 14가 필요합니다. 이 기기에는 예측형 뒤로 가기 동작이 없어 이 항목은 효과가 없습니다.",
        "每半天左右让系统挑个合适时机检查一次，有变化才提醒；同一批更新只提醒一次。只用连载列表和你本地的阅读时间，不上传你在看什么。默认关闭。" to "반나절에 한 번쯤 시스템이 적당한 시점을 골라 확인하고, 변화가 있을 때만 알립니다. 같은 묶음의 업데이트는 한 번만 알립니다. 구독 목록과 기기의 읽은 시간만 사용하며 무엇을 보는지는 업로드하지 않습니다. 기본값은 꺼짐입니다.",
        "取系统壁纸的配色（Android 12+）。Material 风格会整份跟随系统；另外几套玻璃只取强调色，层次仍按本站配色。" to "시스템 배경 화면에서 색을 가져옵니다(Android 12 이상). Material 스타일은 전체가 시스템을 따르고, 다른 유리는 강조색만 가져와 층위는 자체 배색을 유지합니다.",
